-- 2026-10-08: explicitly requested by the user to run during the next deploy.
-- One previously paid, verified response only. No upstream calls, billing
-- changes, secret rotation, automatic platform-wide grants or identity changes.
-- runMigrations executes this entire file and its receipt in one transaction.
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '60s';

CREATE OR REPLACE FUNCTION core.weibo_long_text_preview_of(full_body text, preview text)
RETURNS boolean LANGUAGE sql IMMUTABLE STRICT AS $fn$
  SELECT preview ~ '[[:space:]​‌‍﻿]*(?:[.。…]+[[:space:]]*)?展开(全文)?[cC]?[[:space:]​‌‍﻿]*$'
    AND length(prefix) >= 40 AND length(content) > length(prefix)
    AND starts_with(content, prefix)
  FROM (SELECT
    regexp_replace(regexp_replace(preview,
      '[[:space:]​‌‍﻿]*(?:[.。…]+[[:space:]]*)?展开(全文)?[cC]?[[:space:]​‌‍﻿]*$', ''),
      '[[:space:]​‌‍﻿]', '', 'g') AS prefix,
    regexp_replace(full_body, '[[:space:]​‌‍﻿]', '', 'g') AS content) normalized;
$fn$;

-- Installed before the data change, in the same transaction. This protects
-- against old ingest workers during migrate-before-rollout as well as new ones.
CREATE OR REPLACE FUNCTION core.preserve_verified_weibo_long_text()
RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NEW.deleted_at IS NULL AND OLD.deleted_at IS NULL
     AND NEW.dataset_id = OLD.dataset_id AND NEW.platform = OLD.platform
     AND NEW.object_type = OLD.object_type AND NEW.external_id = OLD.external_id
     AND core.weibo_long_text_preview_of(OLD.body, NEW.body) THEN
    OLD.last_seen_at := GREATEST(OLD.last_seen_at, NEW.last_seen_at);
    RETURN OLD;
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS preserve_weibo_5351726865449966 ON core.canonical_records;
CREATE TRIGGER preserve_weibo_5351726865449966
BEFORE UPDATE ON core.canonical_records FOR EACH ROW
WHEN (OLD.id = '34c72b79-f291-4ef7-ad9b-fe62eb03912d'::uuid
  AND OLD.platform = 'weibo'
  AND OLD.extensions #>> '{weiboLongTextRepair,responseSha256}' =
    'b05ecd61c51bb3e51a1fa464e0ffd78e41c10c0b47363a5b07806bee003444dc')
EXECUTE FUNCTION core.preserve_verified_weibo_long_text();

DO $repair$
DECLARE
  target_id constant uuid := '34c72b79-f291-4ef7-ad9b-fe62eb03912d';
  response_hash constant text := 'b05ecd61c51bb3e51a1fa464e0ffd78e41c10c0b47363a5b07806bee003444dc';
  provider_request constant text := '3b57afa7-2664-4dc7-9e4e-b8b5eb9c86be';
  captured_at constant timestamptz := '2026-10-08T05:56:31.007Z';
  exact_bytes bytea := decode($evidence$$evidence$, 'base64');
  provider_response jsonb;
  full_body text;
  current_record core.canonical_records%ROWTYPE;
  before_record jsonb;
  evidence jsonb;
  raw_evidence jsonb;
  raw_hash text;
  content_hash text;
  next_title text;
  run_id uuid := gen_random_uuid();
  source_id uuid := gen_random_uuid();
  connector constant text := 'manual:tikhub-weibo-long-text';
  stream constant text := 'weibo.post_detail.repair.v1';
BEGIN
  IF encode(sha256(exact_bytes), 'hex') <> response_hash THEN
    RAISE EXCEPTION 'Weibo repair evidence checksum mismatch';
  END IF;
  provider_response := convert_from(exact_bytes, 'UTF8')::jsonb;
  full_body := btrim(provider_response #>> '{data,longText,content}');
  IF provider_response ->> 'code' IS DISTINCT FROM '200'
     OR provider_response ->> 'request_id' IS DISTINCT FROM provider_request
     OR provider_response #>> '{data,idstr}' IS DISTINCT FROM '5351726865449966'
     OR provider_response #>> '{data,user,idstr}' IS DISTINCT FROM '2471317784'
     OR provider_response #>> '{data,isLongText}' IS DISTINCT FROM 'true'
     OR provider_response #>> '{params,is_get_long_text}' IS DISTINCT FROM 'true'
     OR full_body IS NULL OR char_length(full_body) <> 411
     OR btrim(provider_response #>> '{data,text_raw}') IS DISTINCT FROM full_body THEN
    RAISE EXCEPTION 'Weibo repair evidence identity or full-text fields mismatch';
  END IF;

  SELECT * INTO current_record FROM core.canonical_records WHERE id=target_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE NOTICE 'Weibo repair skipped: target record absent in this database';
    RETURN;
  END IF;
  IF current_record.dataset_id <> 'night-all.search.v1' OR current_record.platform <> 'weibo'
     OR current_record.object_type <> 'post' OR current_record.external_id <> '5351726865449966'
     OR current_record.author_external_id IS DISTINCT FROM '2471317784'
     OR current_record.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Weibo repair refused: canonical identity changed or deleted';
  END IF;
  IF current_record.extensions #>> '{weiboLongTextRepair,responseSha256}' = response_hash
     AND current_record.body = full_body THEN
    RAISE NOTICE 'Weibo repair already applied';
    RETURN;
  END IF;
  IF current_record.body IS DISTINCT FROM full_body
     AND NOT coalesce(core.weibo_long_text_preview_of(full_body, current_record.body), false) THEN
    RAISE EXCEPTION 'Weibo repair refused: current body is no longer the verified preview';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM core.record_revisions WHERE record_id=target_id
      AND revision=current_record.current_revision AND payload_sha256=current_record.payload_sha256) THEN
    RAISE EXCEPTION 'Weibo repair refused: current revision history is missing or inconsistent';
  END IF;
  before_record := to_jsonb(current_record);
  next_title := CASE WHEN current_record.title = current_record.body THEN full_body ELSE current_record.title END;
  evidence := jsonb_build_object('parserVersion','mxih-weibo-long-text-repair.v1',
    'provider','tikhub','endpoint','/api/v1/weibo/web_v2/fetch_post_detail',
    'params',jsonb_build_object('id','5351726865449966','is_get_long_text',true),
    'requestId',provider_request,'responseSha256',response_hash,'capturedAt',captured_at,
    'previousRevision',current_record.current_revision,'previousPayloadSha256',current_record.payload_sha256,
    'billingSource','supplier-direct-user-authorized','migration','131_weibo_long_text_and_lcy_grants.sql');
  raw_evidence := jsonb_build_object('response',provider_response,
    'exactResponseBase64',encode(exact_bytes,'base64'),'evidence',evidence,'previousCanonical',before_record);
  raw_hash := encode(sha256(convert_to(raw_evidence::text,'UTF8')),'hex');
  content_hash := encode(sha256(convert_to(jsonb_build_object('body',full_body,'title',next_title,
    'previousPayloadSha256',current_record.payload_sha256,'evidence',evidence)::text,'UTF8')),'hex');

  INSERT INTO ingest.ingest_runs(id,connector_id,stream_id,trigger,item_count,finished_at)
    VALUES(run_id,connector,stream,'manual_full_text_repair',1,now());
  INSERT INTO ingest.source_objects(id,connector_id,stream_id,object_type,source_key,
      payload_sha256,raw_payload_hash_version,raw_payload,source_updated_at,ingest_run_id)
    VALUES(source_id,connector,stream,'post','5351726865449966:'||response_hash,
      raw_hash,1,raw_evidence,captured_at,run_id);
  INSERT INTO ingest.source_object_revisions(source_object_id,revision,payload_sha256,payload_hash_version,
      raw_payload,source_updated_at,ingest_run_id)
    VALUES(source_id,1,raw_hash,1,raw_evidence,captured_at,run_id);
  UPDATE core.canonical_records SET title=next_title,body=full_body,
      extensions=extensions||jsonb_build_object('weiboLongTextRepair',evidence),payload_sha256=content_hash,
      current_revision=current_revision+1,projection_revision=projection_revision+1
    WHERE id=target_id RETURNING * INTO current_record;
  INSERT INTO core.record_revisions(record_id,revision,payload_sha256,normalized_payload,parser_version,ingest_run_id)
    VALUES(target_id,current_record.current_revision,content_hash,to_jsonb(current_record),'mxih-weibo-long-text-repair.v1',run_id);
  INSERT INTO core.observations(id,record_id,connector_id,source_event_id,observed_at,observation_hash,ingest_run_id)
    VALUES(gen_random_uuid(),target_id,connector,provider_request,captured_at,response_hash,run_id);
  INSERT INTO outbox.projection_events(aggregate_type,aggregate_id,event_type,projection_revision,payload)
    VALUES('canonical_record',target_id,'upsert',current_record.projection_revision,
      jsonb_build_object('datasetId',current_record.dataset_id,'platform','weibo','objectType','post'));
  RAISE NOTICE 'Weibo repaired: % characters, revision %, projection %',
    char_length(full_body),current_record.current_revision,current_record.projection_revision;
END
$repair$;

DO $grants$
DECLARE
  tenant constant uuid := '277bf8a4-5ed5-414d-b429-d72fcd7d36b6';
  consumer constant uuid := 'be7d07fe-3d98-4db3-b00d-e5cbe5a76190';
  selected_key api_keys%ROWTYPE;
  baseline api_key_platform_entitlements%ROWTYPE;
  previous_scopes jsonb;
  next_scopes jsonb;
  capability_name text;
  operations constant text[] := ARRAY['native.t.weibo_web_v2_fetch_realtime_search','native.t.api_4f35621a9c07e539'];
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('tenant-access:'||tenant::text));
  IF NOT EXISTS(SELECT 1 FROM consumers WHERE id=consumer AND tenant_id=tenant) THEN
    RAISE NOTICE 'LCY Weibo grant skipped: original consumer absent in this database';
    RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tenants WHERE id=tenant AND status='active')
     OR NOT EXISTS(SELECT 1 FROM consumers WHERE id=consumer AND status='active') THEN
    RAISE EXCEPTION 'LCY Weibo grant refused: original tenant/consumer is inactive';
  END IF;
  IF (SELECT count(*) FROM api_keys WHERE tenant_id=tenant AND consumer_id=consumer
      AND name='LCY-delta' AND id::text LIKE 'fd2f8cc9-%') <> 1 THEN
    RAISE EXCEPTION 'LCY Weibo grant refused: original Key missing or ambiguous';
  END IF;
  SELECT * INTO selected_key FROM api_keys WHERE tenant_id=tenant AND consumer_id=consumer
    AND name='LCY-delta' AND id::text LIKE 'fd2f8cc9-%' FOR UPDATE;
  IF selected_key.status <> 'active' OR selected_key.environment <> 'live'
     OR selected_key.scope_mode <> 'snapshot' OR selected_key.expires_at IS NULL
     OR selected_key.expires_at <= now() THEN
    RAISE EXCEPTION 'LCY Weibo grant refused: original Key is unavailable';
  END IF;
  IF EXISTS(SELECT 1 FROM api_keys WHERE consumer_id=consumer AND id<>selected_key.id
      AND status='active' AND scope_mode='legacy_dynamic') THEN
    RAISE EXCEPTION 'LCY Weibo grant refused: a sibling dynamic Key could inherit new grants';
  END IF;
  SELECT * INTO baseline FROM api_key_platform_entitlements WHERE api_key_id=selected_key.id AND platform='weibo';
  IF NOT FOUND THEN RAISE EXCEPTION 'LCY Weibo grant requires original Weibo quota snapshot'; END IF;
  previous_scopes := jsonb_build_object('scopeMode',selected_key.scope_mode,'webSearchOrder',selected_key.web_search_order,
    'platforms',(SELECT coalesce(jsonb_agg(platform ORDER BY platform),'[]') FROM api_key_platform_entitlements WHERE api_key_id=selected_key.id),
    'capabilities',(SELECT coalesce(jsonb_agg(capability ORDER BY capability),'[]') FROM api_key_capability_entitlements WHERE api_key_id=selected_key.id));

  PERFORM pg_advisory_xact_lock(hashtext(consumer::text||':authorization:platform:social'));
  INSERT INTO platform_grants(consumer_id,platform) VALUES(consumer,'social') ON CONFLICT DO NOTHING;
  INSERT INTO consumer_platform_policies(tenant_id,consumer_id,platform,max_requests,window_seconds,max_page_size)
    VALUES(tenant,consumer,'social',baseline.max_requests,baseline.window_seconds,baseline.max_page_size) ON CONFLICT DO NOTHING;
  INSERT INTO api_key_platform_entitlements(api_key_id,platform,max_requests,window_seconds,max_page_size)
    SELECT selected_key.id,'social',least(max_requests,baseline.max_requests),greatest(window_seconds,baseline.window_seconds),
      least(max_page_size,baseline.max_page_size) FROM consumer_platform_policies WHERE consumer_id=consumer AND platform='social'
    ON CONFLICT DO NOTHING;
  FOREACH capability_name IN ARRAY operations LOOP
    PERFORM pg_advisory_xact_lock(hashtext(consumer::text||':authorization:capability:'||capability_name));
    INSERT INTO capability_grants(consumer_id,capability) VALUES(consumer,capability_name) ON CONFLICT DO NOTHING;
    INSERT INTO consumer_capability_policies(tenant_id,consumer_id,capability,max_requests,window_seconds)
      VALUES(tenant,consumer,capability_name,baseline.max_requests,baseline.window_seconds) ON CONFLICT DO NOTHING;
    INSERT INTO api_key_capability_entitlements(api_key_id,capability,max_requests,window_seconds)
      SELECT selected_key.id,capability_name,least(max_requests,baseline.max_requests),greatest(window_seconds,baseline.window_seconds)
        FROM consumer_capability_policies WHERE consumer_id=consumer AND capability=capability_name ON CONFLICT DO NOTHING;
  END LOOP;
  next_scopes := jsonb_build_object('scopeMode',selected_key.scope_mode,'webSearchOrder',selected_key.web_search_order,
    'platforms',(SELECT coalesce(jsonb_agg(platform ORDER BY platform),'[]') FROM api_key_platform_entitlements WHERE api_key_id=selected_key.id),
    'capabilities',(SELECT coalesce(jsonb_agg(capability ORDER BY capability),'[]') FROM api_key_capability_entitlements WHERE api_key_id=selected_key.id));
  IF next_scopes IS DISTINCT FROM previous_scopes THEN
    INSERT INTO api_key_scope_events(api_key_id,actor,previous_scopes,next_scopes)
      VALUES(selected_key.id,'migration-131:user-authorized-weibo',previous_scopes,next_scopes);
  END IF;
  RAISE NOTICE 'LCY-delta original Key has social + Weibo native search/detail scopes; existing scopes/limits preserved';
END
$grants$;
